//! Desktop application of the `aero` toolkit.
//!
//! The Tauri layer is deliberately thin: [`commands`] forwards to the
//! Tauri-independent [`engine`], which uses the `aero-geometry`,
//! `aero-foil2d` and `aero-optim` crates. TypeScript bindings for every command and type are
//! generated by `tauri-specta` into `app/src/lib/bindings.ts`.

pub mod catalogue;
pub mod commands;
pub mod design;
pub mod dto;
pub mod engine;
pub mod error;
pub mod export;
pub mod model;

use std::path::Path;
use std::sync::Arc;

use specta_typescript::Typescript;

/// Builder listing every command exposed to the frontend.
pub fn specta_builder() -> tauri_specta::Builder<tauri::Wry> {
    tauri_specta::Builder::<tauri::Wry>::new()
        .commands(tauri_specta::collect_commands![
            commands::app_info,
            commands::get_session,
            commands::new_session,
            commands::create_naca,
            commands::import_airfoil,
            commands::create_naca_series,
            commands::preview_modification,
            commands::apply_modification,
            commands::flap_series,
            commands::design_start,
            commands::design_edit,
            commands::design_preview,
            commands::design_apply,
            commands::design_close,
            commands::get_camber_thickness,
            commands::import_paths,
            commands::add_examples,
            commands::get_catalogue,
            commands::add_from_catalogue,
            commands::set_airfoils_visible,
            commands::delete_airfoils,
            commands::duplicate_airfoil,
            commands::rename_airfoil,
            commands::delete_airfoil,
            commands::set_airfoil_visible,
            commands::get_geometry,
            commands::set_paneling,
            commands::normalize_airfoil,
            commands::analyze,
            commands::update_settings,
            commands::run_sweep,
            commands::cancel_sweep,
            commands::run_optimization,
            commands::cancel_optimization,
            commands::update_optimization_setup,
            commands::add_optimized_airfoil,
            commands::export_dat,
            commands::export_polars_csv,
            commands::export_cp_csv,
            commands::export_boundary_layer_csv,
            commands::write_file,
            commands::save_project,
            commands::open_project,
        ])
        // Counts (number of panel nodes, ...) are far below 2^53.
        .dangerously_cast_bigints_to_number()
}

/// Writes the TypeScript bindings to `path`.
pub fn export_bindings(path: &Path) -> Result<(), String> {
    specta_builder()
        .export(
            Typescript::default()
                .header("// Generated by tauri-specta from the Rust types. Do not edit.\n"),
            path,
        )
        .map_err(|e| e.to_string())
}

/// Runs the desktop application.
pub fn run() -> Result<(), tauri::Error> {
    let builder = specta_builder();
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .manage(Arc::new(engine::Engine::new()))
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            Ok(())
        })
        .run(tauri::generate_context!())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Fails when `app/src/lib/bindings.ts` does not match the Rust types.
    /// Regenerate with `npm run bindings` (or `AERO_UPDATE_BINDINGS=1 cargo
    /// test -p aero-app bindings`).
    #[test]
    fn bindings_are_up_to_date() {
        let committed = Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/lib/bindings.ts");
        let generated =
            std::env::temp_dir().join(format!("aero-bindings-{}.ts", std::process::id()));
        export_bindings(&generated).unwrap();
        let fresh = std::fs::read_to_string(&generated)
            .unwrap()
            .replace("\r\n", "\n");
        std::fs::remove_file(&generated).ok();
        if std::env::var_os("AERO_UPDATE_BINDINGS").is_some() {
            std::fs::write(&committed, &fresh).unwrap();
            return;
        }
        let current = std::fs::read_to_string(&committed)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        assert!(
            current == fresh,
            "app/src/lib/bindings.ts is out of date: run `npm run bindings` in app/"
        );
    }
}
